for name,url in [('arc-rpc','https://docs.arc.io/arc/references/rpc-endpoints.md'),('arc-evm','https://docs.arc.io/arc/references/evm-differences.md'),('cf-limits','https://developers.cloudflare.com/workers/platform/limits/index.md'),('d1-limits','https://developers.cloudflare.com/d1/platform/limits/index.md')]:
    try:
        req=urllib.request.Request(url,headers={'User-Agent':'RetempoPhase6ReadOnlyResearch/1.0'})
        with urllib.request.urlopen(req,timeout=20) as r: data=r.read(250000)
        p=OUT/(name+'.md'); p.write_bytes(data)
        report['docs'].append({'url':url,'path':str(p),'sha256':digest(p),'bytes':len(data)})
    except Exception as e: report['docs'].append({'url':url,'error':str(e)})

def rpc(method,params):
    ident=len(report['observations'])+1
    payload={'jsonrpc':'2.0','id':ident,'method':method,'params':params}
    record={'method':method,'params':params,'id':ident}
    req=urllib.request.Request(report['endpoint'],data=json.dumps(payload).encode(),headers={'Content-Type':'application/json','User-Agent':'RetempoPhase6ReadOnlyResearch/1.0'},method='POST')
    try:
        with urllib.request.urlopen(req,timeout=18) as r:
            record['httpStatus']=r.status
            data=r.read(524289)
        record['bytesRead']=len(data);record['overflow']=len(data)>524288
        p=OUT/f'rpc-{ident:02}-{method}.json';p.write_bytes(data)
        record['rawPath']=str(p);record['rawSha256']=digest(p)
        if record['overflow']: value=None
        else:
            body=json.loads(data);record['error']=body.get('error');value=body.get('result')
            if isinstance(value,list):record['resultCount']=len(value)
            elif isinstance(value,dict):record['resultKeys']=list(value)
            elif value is not None:record['resultScalar']=value
    except Exception as e:
        record['transportError']=str(e);value=None
    report['observations'].append(record)
    (OUT/'public-probe.json').write_text(json.dumps(report,indent=2)+'\n')
    time.sleep(.3)
    return value
